%[text] # 3 DoF mass-spring oscillator example
%[text] Worked example of the mass-spring system found in [Evaluating applied force reduced-order models: validation | Research Square](https://www.researchsquare.com/article/rs-8723275/v1)
%[text] Make sure '`AFR_tool.prj`' is open
%%
%[text] The logging and visualisation levels determine how much is outputted to the console and as graphical representations respectively. The higher the number ( ∈ {0,1,2,3,4}) the more verbose the output.
clear
set_script_wd(); %sets working directory to "...\mass_spring_system"
set_logging_level(3)
set_visualisation_level(3)

%%
%[text] ## {1}-ROM
%[text] ### Static dataset 
%[text] To create the {1}-ROM, the system (as defined in [.\\geometry\\mass\_spring\_roller\\mass\_spring\_roller.m](file:.\geometry\mass_spring_roller\mass_spring_roller.m)), ROM limit and reduction basis needs to be specified.
%[text] Additionally the tangent stiffness at each loadcase is requested for later validation.
%--------- System Settings ---------%
system_name = "mass_spring_roller";
energy_limit = 0.06;
reduction_basis = 1;
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.additional_data = "stiffness";
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:25b6434e]
Static_Data = Static_Dataset(Model); %[output:660f2d97] %[output:55d978dd] %[output:816151f0] %[output:144e07e1] %[output:09720d2d] %[output:0bd36b91]
Static_Data.save_data; %[output:75d2abf5]
%%
%[text] ### Periodic orbits
%[text] Dynamic solutions are stored as a '`Dynamic_Dataset`' class. Here the instance is initialised, linked to the static dataset and the maximum displacement at the second DoF is requested for each orbit.
rom_name = "mass_spring_roller_1";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:86d86edd]
Dyn_Data = Dyn_Data.remove_solution("all");

Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
Additional_Output.dof = 2;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);
%[text] The `Continuation_Opts` map to the corresponding continuation and collocation settings in COCO.
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-1;
Continuation_Opts.max_inc = 1e-1;
Continuation_Opts.min_inc = 1e-3;

Continuation_Opts.min_discretisation_num = 20;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.frequency_points = [1.86,3]; %adds frequency events to the continutation problem
%-----------------------------------------%

Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:3b184afb]
compare_solutions("energy","mass_spring_roller_1","all"); %[output:2262ed0e] %[output:8fd2c51d]
%%
%[text] ### Validation
%[text] The backbone predicted by the {1}-ROM can now be validated against a {1,2} and {1,3} validation basis. 
compare_validation("mass_spring_roller_1","validation error",1,"all"); %[output:625ea5e9] %[output:20a5bc18] %[output:8fc5d55c] %[output:0ccdb086] %[output:9382a160] %[output:018688f4] %[output:458b2840] %[output:4c4b4f40] %[output:8311f969] %[output:211043e7] %[output:3a310f80] %[output:25e364d6] %[output:7a1dce94] %[output:08ca7a96] %[output:563fb10a] %[output:15d64c76] %[output:88b01258] %[output:3a659eaa] %[output:720cc976] %[output:495f6a4d] %[output:8b3c2483] %[output:56507c19] %[output:180b6d77] %[output:696f3c82] %[output:69c97ba0] %[output:0709c790] %[output:97de685a] %[output:28194d05] %[output:515c3972] %[output:3b09e689] %[output:1db0e00a] %[output:579a90f0] %[output:61961c08] %[output:9d1de785] %[output:6f1c0051] %[output:771b5c9e] %[output:6103d4ad] %[output:2183cf27] %[output:6ccb1414] %[output:95c7ff1a] %[output:1bc0c488] %[output:431ee046] %[output:2acc0a88] %[output:5f74940c] %[output:407fb6b2] %[output:5b87d44c] %[output:71ea3922] %[output:8c8d9af6] %[output:10111212] %[output:25231188] %[output:2b613f59] %[output:51631762] %[output:4c3de48f] %[output:0ac441c3] %[output:6b9afd3d] %[output:8795dfde] %[output:7c55ec5a] %[output:4837b4d0] %[output:01f3dc95] %[output:17e9b2f1] %[output:154d871c] %[output:2e0c7a1a] %[output:4dac67ab] %[output:6bc0127f] %[output:611206c4] %[output:04f0bf32] %[output:5b46e5b6] %[output:268d2635] %[output:4f235c9a] %[output:01bd64a9] %[output:5d4911cc] %[output:3cd50eff] %[output:8b9599d2] %[output:6bf97840]
%%
%[text] ## {1,2}-ROM
%[text] ### Static dataset
%--------- System Settings ---------%
system_name = "mass_spring_roller";
energy_limit = 0.06;
reduction_basis = [1,2];
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.additional_data = "stiffness";
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:947149e4]
Static_Data = Static_Dataset(Model); %[output:63263aac] %[output:73a4345b] %[output:0c998dae] %[output:273ef712] %[output:28412efc] %[output:475943eb]
Static_Data.save_data; %[output:8c389e7f]
%%
%[text] ### Periodic orbits
rom_name = "mass_spring_roller_12";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:6b94d2b8]
Dyn_Data = Dyn_Data.remove_solution("all");

Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
Additional_Output.dof = 2;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);

%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-1;
Continuation_Opts.max_inc = 1e-1;
Continuation_Opts.min_inc = 1e-3;

Continuation_Opts.forward_steps = 200;

Continuation_Opts.min_discretisation_num = 20;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.frequency_points = [1.86,3]; %adds frequency events to the continutation problem
%-----------------------------------------%

Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:30b39d4b]
compare_solutions("energy","mass_spring_roller_1","all","mass_spring_roller_12","all") %[output:811070c1] %[output:49f34f52] %[output:3edcbfe1]
%%
%[text] ### Validation
compare_validation("mass_spring_roller_12","validation error",1,"all"); %[output:560a7d0d] %[output:0ff4f554] %[output:01a86a40] %[output:1e98d540] %[output:1c4b079a] %[output:87a035d9] %[output:51735b7c] %[output:3cefe3e0] %[output:9c3f48d5] %[output:70062406] %[output:2e4afb83] %[output:637fb435] %[output:670ce93f] %[output:67a79c8e] %[output:4f5c85d4] %[output:4ed35c56] %[output:3b715bb7] %[output:1b30bf4b] %[output:18a6a812]

